<script setup>
import {onBeforeUnmount,ref,watch} from 'vue';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {api} from '../services/accounting.js';
import {integrationStatus,integrationIssues,integrationError} from '../services/integrations.js';
import {reportMoney as money,reportDate as date} from '../services/report-format.js';
import FormDialog from './FormDialog.vue';
import InvoiceForm from './InvoiceForm.vue';
const emit=defineEmits(['posted']);
const {company,selectExercise}=useContext(),{can}=useAccess();
const rows=ref([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),detail=ref(null),posting=ref(null);let generation=0;
const expenseAccounts=ref([]),expenseEditing=ref(false),expenseAccount=ref(''),rememberExpense=ref(true);
async function load(){const ticket=++generation;loading.value=true;error.value='';try{const result=await api('/integration-invoices?'+new URLSearchParams({page:page.value,search:search.value}));if(ticket===generation){rows.value=result.rows;total.value=result.total;}}catch(cause){if(ticket===generation)error.value=integrationError(cause);}finally{if(ticket===generation)loading.value=false;}}
watch(()=>company.value?.id,()=>{detail.value=null;posting.value=null;rows.value=[];page.value=1;void load();},{immediate:true});
async function open(row){busy.value=true;error.value='';expenseEditing.value=false;expenseAccount.value='';rememberExpense.value=true;const ticket=generation;try{const result=await api('/integration-invoices/'+row.id);if(ticket===generation){detail.value=result;if(result.can_change_expense&&can('accounting_write')){expenseAccounts.value=(await api('/accounts?kind=subaccount')).filter(account=>account.kind==='subaccount'&&/^[62]/.test(account.code));expenseEditing.value=!result.expense_suggestion;}}}catch(cause){error.value=integrationError(cause);}finally{busy.value=false;}}
async function changeExpense(){if(!expenseAccount.value||busy.value)return;busy.value=true;error.value='';try{detail.value=await api('/integration-invoices/'+detail.value.id+'/expense-account',{method:'POST',body:{version:detail.value.version,account_id:Number(expenseAccount.value),remember:rememberExpense.value}});expenseEditing.value=false;notice.value=rememberExpense.value?'Cuenta de gasto corregida y recordada para las próximas facturas del proveedor.':'Cuenta de gasto corregida.';await load();}catch(cause){error.value=integrationError(cause);}finally{busy.value=false;}}
function beginPosting(){const target=detail.value;selectExercise(String(target.form.exercise_id));detail.value=null;posting.value=target;}
async function posted(result){posting.value=null;notice.value='Factura contabilizada mediante el flujo contable habitual.';await load();emit('posted',result.id);}
async function cancel(){busy.value=true;error.value='';try{await api('/integration-invoices/'+detail.value.id+'/cancel',{method:'POST',body:{version:detail.value.version}});detail.value=null;notice.value='Recepción anulada. Se conserva su trazabilidad y no se ha generado ningún asiento.';await load();}catch(cause){error.value=integrationError(cause);}finally{busy.value=false;}}
onBeforeUnmount(()=>generation++);
</script>
<template>
 <section aria-label="Facturas recibidas por integración">
  <h2>Facturas recibidas de otros sistemas</h2><p class="muted">Datos enviados por Gestió y otros programas autorizados. La recepción no genera asientos. Los PDF permanecen en el sistema de origen.</p>
  <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
  <form class="filters" @submit.prevent="page=1;load()"><label>Buscar<input v-model="search" type="search" maxlength="200" placeholder="Proveedor, número o identificador externo"></label><button class="button" :disabled="loading||busy">Actualizar</button></form>
  <p v-if="loading" role="status">Cargando facturas importadas…</p>
  <div v-else class="table-wrap panel"><table class="invoices-table"><thead><tr><th>Origen y referencia</th><th>Empresa</th><th>Proveedor</th><th>Factura</th><th>Fecha</th><th class="amount">Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.source_system }}<small class="trade-cell-note">{{ row.external_id }}</small></td><td>{{ row.company_name }}</td><td>{{ row.supplier_name }}<small class="trade-cell-note">{{ row.supplier_tax_id }}</small></td><td>{{ row.invoice_number }}</td><td>{{ date(row.invoice_date) }}</td><td class="amount">{{ money(row.total_amount) }} {{ row.currency }}</td><td><span class="badge">{{ integrationStatus[row.accounting_status] }}</span><small v-if="row.possible_duplicate" class="trade-cell-note">Posible duplicado fiscal</small><small v-if="row.issues.length" class="trade-cell-note">{{ row.issues.length }} observación(es)</small></td><td><button class="button" :disabled="busy" @click="open(row)">Consultar</button></td></tr><tr v-if="!rows.length"><td colspan="8" class="empty-cell">No hay facturas recibidas por integración para esta búsqueda.</td></tr></tbody></table></div>
  <div class="actions"><button class="button" :disabled="page===1||loading||busy" @click="page--;load()">Anterior</button><span>Página {{ page }} · {{ total }} facturas</span><button class="button" :disabled="page*50>=total||loading||busy" @click="page++;load()">Siguiente</button></div>
  <FormDialog v-if="detail" class="imported-invoice-dialog" :title="'Factura recibida · '+detail.invoice_number" :busy="busy" @close="detail=null">
   <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
   <section class="imported-invoice-section" aria-label="Proveedor y empresa"><h3>Proveedor y empresa</h3>
    <table class="imported-invoice-facts"><tbody><tr><th scope="row">Proveedor</th><td><strong>{{ detail.supplier_name }}</strong></td></tr><tr><th scope="row">CIF / NIF</th><td>{{ detail.supplier_tax_id||'No informado' }}</td></tr><tr><th scope="row">Empresa</th><td>{{ detail.company_name }}</td></tr></tbody></table>
   </section>
   <section class="imported-invoice-section" aria-label="Datos de la factura"><h3>Datos de la factura</h3>
    <table class="imported-invoice-facts"><tbody><tr><th scope="row">Número de factura</th><td>{{ detail.invoice_number }}</td></tr><tr><th scope="row">Fecha de factura</th><td>{{ date(detail.invoice_date) }}</td></tr><tr><th scope="row">Vencimiento</th><td>{{ date(detail.due_date) }}</td></tr><tr><th scope="row">Estado</th><td><span class="badge">{{ integrationStatus[detail.accounting_status] }}</span></td></tr></tbody></table>
   </section>
   <section class="imported-invoice-section" aria-label="Concepto"><h3>Concepto</h3><p class="imported-invoice-concept">{{ detail.payload.description }}</p></section>
   <section v-if="detail.payload.rectification" class="imported-invoice-section" aria-label="Rectificación"><h3>Rectificación</h3><table class="imported-invoice-facts"><tbody><tr><th scope="row">Factura original</th><td>{{ detail.payload.rectification.originalInvoiceNumber }}</td></tr><tr><th scope="row">Motivo</th><td>{{ detail.payload.rectification.reason }}</td></tr></tbody></table></section>
   <section class="imported-invoice-section" aria-label="Desglose de IVA"><h3>Desglose de IVA</h3>
    <div class="table-wrap"><table><thead><tr><th>Tratamiento</th><th class="amount">Base</th><th class="amount">IVA %</th><th class="amount">Cuota</th></tr></thead><tbody><tr v-for="(tax,index) in detail.payload.taxBreakdown" :key="index"><td>{{ {vat:'IVA',exempt:'Exento',not_subject:'No sujeto',reverse_charge:'Inversión del sujeto pasivo'}[tax.taxType]||tax.taxType }}<small class="trade-cell-note">{{ tax.exemptionReason }}</small></td><td class="amount">{{ money(tax.taxableBase) }}</td><td class="amount">{{ tax.taxRate }}</td><td class="amount">{{ money(tax.taxAmount) }}</td></tr></tbody></table></div>
   </section>
   <section v-if="detail.payload.withholdings.length" class="imported-invoice-section" aria-label="Retenciones"><h3>Retenciones</h3><div class="table-wrap"><table><thead><tr><th class="amount">Base</th><th class="amount">Retención %</th><th class="amount">Importe</th></tr></thead><tbody><tr v-for="(retention,index) in detail.payload.withholdings" :key="index"><td class="amount">{{ money(retention.base) }}</td><td class="amount">{{ retention.rate }}</td><td class="amount">{{ money(retention.amount) }} {{ detail.currency }}</td></tr></tbody></table></div></section>
   <div class="imported-invoice-total"><span>Total de la factura</span><strong>{{ money(detail.total_amount) }} {{ detail.currency }}</strong></div>
   <section class="imported-invoice-section" aria-label="Cuenta de gasto"><h3>Cuenta de gasto o inmovilizado</h3>
    <p v-if="detail.current_expense_account"><strong>{{ detail.current_expense_account.code }} · {{ detail.current_expense_account.description }}</strong></p>
    <p v-else-if="detail.expense_suggestion" class="notice">Cuenta recordada para este proveedor: <strong>{{ detail.expense_suggestion.code }} · {{ detail.expense_suggestion.description }}</strong>. Podrás revisarla al contabilizar.</p>
    <p v-else class="notice">Todavía no hay una cuenta guardada para este proveedor. El programa te pedirá que la selecciones y la recordará para las próximas facturas.</p>
    <template v-if="detail.can_change_expense&&can('accounting_write')"><button v-if="!expenseEditing" type="button" class="button" @click="expenseEditing=true;expenseAccount=''">Cambiar cuenta de gasto</button>
     <form v-if="expenseEditing" class="imported-expense-form" @submit.prevent="changeExpense"><p>Selecciona la cuenta correcta para esta factura. Se actualizará también la línea de gasto del asiento, conservando sus importes y recibos.</p><label>Cuenta de gasto o inmovilizado<select v-model="expenseAccount" name="correct_expense_account" required :disabled="busy"><option value="">Selecciona la cuenta correcta</option><option v-for="account in expenseAccounts" :key="account.id" :value="account.id">{{ account.code }} · {{ account.description }}</option></select></label><label class="expense-memory-choice"><input v-model="rememberExpense" type="checkbox" :disabled="busy"> Recordar para las próximas facturas de este proveedor</label><button class="button primary" :disabled="busy||!expenseAccount">Guardar cuenta de gasto</button></form>
    </template>
   </section>
   <details v-if="detail.payload.lines.length"><summary>Líneas originales</summary><ul><li v-for="(line,index) in detail.payload.lines" :key="index">{{ line.description }} · {{ money(line.taxableBase) }} · IVA {{ line.taxRate }} % · cuota {{ money(line.taxAmount) }}</li></ul></details>
   <section class="imported-invoice-section" aria-label="Origen e importación"><h3>Origen e importación</h3><table class="imported-invoice-facts"><tbody><tr><th scope="row">Sistema de origen</th><td>{{ detail.source_system }}</td></tr><tr><th scope="row">Referencia externa</th><td>{{ detail.external_id }}</td></tr><tr><th scope="row">Importada (UTC)</th><td>{{ date(String(detail.imported_at).slice(0,10)) }} · {{ String(detail.imported_at).slice(11,19) }}</td></tr><tr><th scope="row">Documento original</th><td><strong>{{ detail.document_external_id }}</strong></td></tr></tbody></table></section><p class="muted">La referencia no es una URL pública. La consulta del PDF estará disponible cuando Gestió disponga de su API documental autenticada.</p>
   <ul v-if="detail.issues.length" class="notice"><li v-for="issue in detail.issues" :key="issue">{{ integrationIssues[issue]||issue }}</li></ul>
   <div class="actions"><button v-if="can('accounting_write')&&detail.can_post" class="button primary" :disabled="busy" @click="beginPosting">Revisar y contabilizar</button><button v-if="detail.accounting_status==='posted'&&detail.invoice_id" class="button" @click="emit('posted',detail.invoice_id);detail=null">Abrir factura contabilizada</button><button v-if="can('accounting_write')&&['pending','issues'].includes(detail.accounting_status)" class="button" :disabled="busy" @click="cancel">Anular recepción</button></div>
  </FormDialog>
  <InvoiceForm v-if="posting" direction="received" :initial-value="posting.form" :integration-id="posting.id" :integration-version="posting.version" :expense-suggestion="posting.expense_suggestion" @close="posting=null" @saved="posted" />
 </section>
</template>
